INSERT INTO skills (code, subject_code, name) VALUES
    ('EVEN_ODD', 'MATH', 'Even and Odd Numbers'),
    ('PUNCTUATION_G2', 'ENGLISH', 'Capitals and Punctuation');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('11000000-0000-0000-0000-000000000018', 'G2-EVENODD-01', 'MATH', 'GRADE_2', 10, 'Even and Odd Numbers', 'Tell whether a number can be split into two equal groups.'),
    ('11000000-0000-0000-0000-000000000019', 'G2-ENG-PUNCT-01', 'ENGLISH', 'GRADE_2', 9, 'Capitals, Commas, and End Marks', 'Use capital letters, commas in lists, and the right end marks.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('31000000-0000-0000-0000-000000000001', 'G2-ADD-01', 'ADD_100', 4, 'What is 34 + 21?', 0, '30 + 20 = 50 and 4 + 1 = 5, so 34 + 21 = 55.', 'Add the tens, then the ones.'),
    ('31000000-0000-0000-0000-000000000002', 'G2-ADD-01', 'ADD_100', 5, 'What is 47 + 36?', 1, '7 + 6 = 13, so carry 1 ten: 40 + 30 + 10 + 3 = 83.', 'The ones add up to more than 9, so regroup.'),
    ('31000000-0000-0000-0000-000000000003', 'G2-ADD-01', 'ADD_100', 6, 'What is 60 + 29?', 2, '60 + 29 = 89.', '6 tens plus 2 tens is 8 tens.'),
    ('31000000-0000-0000-0000-000000000004', 'G2-SUB-01', 'SUB_100', 4, 'What is 75 - 40?', 1, '7 tens - 4 tens = 3 tens, so 75 - 40 = 35.', 'Only the tens change.'),
    ('31000000-0000-0000-0000-000000000005', 'G2-SUB-01', 'SUB_100', 5, 'What is 62 - 18?', 2, 'Take 1 ten as 10 ones: 12 - 8 = 4 and 5 - 1 = 4, so 44.', 'You can''t take 8 from 2, so regroup a ten.'),
    ('31000000-0000-0000-0000-000000000006', 'G2-SUB-01', 'SUB_100', 6, 'What is 100 - 25?', 1, '100 - 25 = 75. Think of 4 quarters making a dollar.', 'Count up from 25 to 100.'),
    ('31000000-0000-0000-0000-000000000007', 'G2-PLACE-01', 'PLACE_VALUE', 4, 'What is the value of the 9 in 93?', 1, 'The 9 is in the tens place, so it means 9 tens = 90.', 'Which place is the 9 in?'),
    ('31000000-0000-0000-0000-000000000008', 'G2-PLACE-01', 'PLACE_VALUE', 5, 'What number has 4 hundreds, 2 tens, and 5 ones?', 1, '400 + 20 + 5 = 425.', 'Hundreds first, then tens, then ones.'),
    ('31000000-0000-0000-0000-000000000009', 'G2-PLACE-01', 'PLACE_VALUE', 6, 'How many tens are in 100?', 2, '10 tens make 100.', 'Count by tens to 100.'),
    ('31000000-0000-0000-0000-000000000010', 'G2-SKIP-01', 'SKIP_COUNT', 4, 'Count by 5s: 25, 30, 35, __?', 2, 'Add 5 each time: 35 + 5 = 40.', 'Add 5 more.'),
    ('31000000-0000-0000-0000-000000000011', 'G2-SKIP-01', 'SKIP_COUNT', 5, 'Count by 2s: 12, 14, 16, __?', 0, 'Add 2 each time: 16 + 2 = 18.', 'Add 2 more.'),
    ('31000000-0000-0000-0000-000000000012', 'G2-SKIP-01', 'SKIP_COUNT', 6, 'Count by 10s: 45, 55, 65, __?', 0, 'Add 10 each time: 65 + 10 = 75.', 'Only the tens digit goes up.'),
    ('31000000-0000-0000-0000-000000000013', 'G2-TIME-01', 'TELL_TIME', 4, 'The short hand is on 10 and the long hand is on 12. What time is it?', 2, 'Long hand on 12 means o''clock. Short hand on 10 means 10:00.', 'The short hand tells the hour.'),
    ('31000000-0000-0000-0000-000000000014', 'G2-TIME-01', 'TELL_TIME', 5, 'The long hand is on 6, and the short hand is between 2 and 3. What time is it?', 0, 'Long hand on 6 means half past. The short hand has passed 2, so it is 2:30.', 'Half past means the long hand is on 6.'),
    ('31000000-0000-0000-0000-000000000015', 'G2-TIME-01', 'TELL_TIME', 6, 'What time is it one hour after 6:30?', 0, 'Add one hour to 6:30 to get 7:30.', 'The minutes stay the same; the hour goes up by 1.'),
    ('31000000-0000-0000-0000-000000000016', 'G2-MONEY-01', 'MONEY', 4, 'A dime is worth how many cents?', 0, 'A dime is worth 10 cents.', 'A dime is small but worth more than a nickel.'),
    ('31000000-0000-0000-0000-000000000017', 'G2-MONEY-01', 'MONEY', 5, 'You have 1 quarter and 1 dime. How many cents do you have?', 1, '25 + 10 = 35 cents.', 'Quarter is 25, dime is 10.'),
    ('31000000-0000-0000-0000-000000000018', 'G2-MONEY-01', 'MONEY', 6, 'How many pennies make 1 dollar?', 2, '1 dollar = 100 cents = 100 pennies.', 'A penny is 1 cent.'),
    ('31000000-0000-0000-0000-000000000019', 'G2-MEASURE-01', 'MEASURE_LEN', 4, 'How many inches are in 1 foot?', 1, '1 foot = 12 inches.', 'A standard ruler is 1 foot long.'),
    ('31000000-0000-0000-0000-000000000020', 'G2-MEASURE-01', 'MEASURE_LEN', 5, 'Which unit would you use to measure the length of a room?', 1, 'A room is big, so feet (or meters) make sense.', 'Use a bigger unit for bigger things.'),
    ('31000000-0000-0000-0000-000000000021', 'G2-MEASURE-01', 'MEASURE_LEN', 6, 'A rope is 15 inches long. You cut off 6 inches. How long is it now?', 0, '15 - 6 = 9 inches.', 'Cutting off means subtract.'),
    ('31000000-0000-0000-0000-000000000022', 'G2-SHAPE-01', 'SHAPES_G2', 4, 'How many faces does a cube have?', 2, 'A cube has 6 square faces, like a dice.', 'Think of a dice.'),
    ('31000000-0000-0000-0000-000000000023', 'G2-SHAPE-01', 'SHAPES_G2', 5, 'Which shape has 5 sides?', 0, 'A pentagon has 5 sides.', 'Penta means five.'),
    ('31000000-0000-0000-0000-000000000024', 'G2-SHAPE-01', 'SHAPES_G2', 6, 'Which 3D shape is like a box with all square faces?', 2, 'A cube is a 3D shape with 6 square faces. A square is flat.', 'It is not flat.'),
    ('31000000-0000-0000-0000-000000000025', 'G2-WORD-01', 'WORD_PROB_G2', 4, 'Nina had 15 stickers. She got 10 more, then gave 5 to her brother. How many does she have now?', 0, '15 + 10 = 25, then 25 - 5 = 20.', 'Do one step at a time.'),
    ('31000000-0000-0000-0000-000000000026', 'G2-WORD-01', 'WORD_PROB_G2', 5, 'A bus had 30 people. 12 got off and 8 got on. How many people are on the bus?', 2, '30 - 12 = 18, then 18 + 8 = 26.', 'First subtract the people who got off.'),
    ('31000000-0000-0000-0000-000000000027', 'G2-WORD-01', 'WORD_PROB_G2', 6, 'Pencils come in packs of 5. How many pencils are in 4 packs?', 0, '5 + 5 + 5 + 5 = 20.', 'Skip count by 5s four times.'),
    ('31000000-0000-0000-0000-000000000028', 'G2-ENG-COMP-01', 'COMPREHENSION_G2', 4, 'Read: "Ella planted a sunflower seed. She watered it every day. Soon it was taller than her!" What did Ella plant?', 2, 'The story says she planted a sunflower seed.', 'Look at the first sentence.'),
    ('31000000-0000-0000-0000-000000000029', 'G2-ENG-COMP-01', 'COMPREHENSION_G2', 5, 'Read: "Ella planted a sunflower seed. She watered it every day. Soon it was taller than her!" How did Ella care for it?', 1, 'She watered it every day.', 'Look at the second sentence.'),
    ('31000000-0000-0000-0000-000000000030', 'G2-ENG-COMP-01', 'COMPREHENSION_G2', 6, 'Read: "Leo grabbed his towel and goggles and ran to the pool." What was Leo going to do?', 1, 'Towel, goggles, and a pool all point to swimming.', 'What do you do with goggles at a pool?'),
    ('31000000-0000-0000-0000-000000000031', 'G2-ENG-COMPOUND-01', 'COMPOUND_WORDS', 4, 'Which two words make "rainbow"?', 0, 'Rain + bow = rainbow.', 'Find two real words.'),
    ('31000000-0000-0000-0000-000000000032', 'G2-ENG-COMPOUND-01', 'COMPOUND_WORDS', 5, 'What compound word means a ball you kick with your foot?', 1, 'Foot + ball = football.', 'Which body part kicks?'),
    ('31000000-0000-0000-0000-000000000033', 'G2-ENG-COMPOUND-01', 'COMPOUND_WORDS', 6, 'Which word is made of two smaller words?', 0, 'Tooth + brush = toothbrush.', 'Look for two whole words joined.'),
    ('31000000-0000-0000-0000-000000000034', 'G2-ENG-CONTRACT-01', 'CONTRACTIONS', 4, 'What is the contraction for "can not"?', 0, 'Can not becomes can''t.', 'The apostrophe replaces the missing letters.'),
    ('31000000-0000-0000-0000-000000000035', 'G2-ENG-CONTRACT-01', 'CONTRACTIONS', 5, 'What does "we''re" stand for?', 1, 'We''re means we are.', 'The ''re is short for are.'),
    ('31000000-0000-0000-0000-000000000036', 'G2-ENG-CONTRACT-01', 'CONTRACTIONS', 6, 'What is the contraction for "she will"?', 1, 'She will becomes she''ll.', '''ll is short for will.'),
    ('31000000-0000-0000-0000-000000000037', 'G2-ENG-SYNANT-01', 'SYNONYMS_ANTONYMS', 4, 'Which word is the opposite of "early"?', 1, 'Early and late are opposites.', 'If you aren''t early, you are...'),
    ('31000000-0000-0000-0000-000000000038', 'G2-ENG-SYNANT-01', 'SYNONYMS_ANTONYMS', 5, 'Which word means the same as "tiny"?', 0, 'Tiny and little both mean very small.', 'Think of an ant.'),
    ('31000000-0000-0000-0000-000000000039', 'G2-ENG-SYNANT-01', 'SYNONYMS_ANTONYMS', 6, 'Which word is the opposite of "quiet"?', 0, 'Quiet and loud are opposites.', 'A drum is...'),
    ('31000000-0000-0000-0000-000000000040', 'G2-ENG-POS-01', 'PARTS_OF_SPEECH_G2', 4, 'In "The happy girl sang," which word is the adjective?', 1, '"happy" describes the girl.', 'Which word describes?'),
    ('31000000-0000-0000-0000-000000000041', 'G2-ENG-POS-01', 'PARTS_OF_SPEECH_G2', 5, 'In "Jack kicked the ball," which word is the verb?', 1, '"kicked" is the action.', 'What did Jack do?'),
    ('31000000-0000-0000-0000-000000000042', 'G2-ENG-POS-01', 'PARTS_OF_SPEECH_G2', 6, 'Which word is a noun?', 2, 'A garden is a place, so it is a noun.', 'Nouns are people, places, or things.'),
    ('31000000-0000-0000-0000-000000000043', 'G2-ENG-PLURAL-01', 'PLURALS', 4, 'What is the plural of "child"?', 0, 'Child is irregular: one child, two children.', 'This one doesn''t use -s.'),
    ('31000000-0000-0000-0000-000000000044', 'G2-ENG-PLURAL-01', 'PLURALS', 5, 'What is the plural of "leaf"?', 2, 'Leaf changes f to v and adds -es: leaves.', 'Think of fall: lots of...'),
    ('31000000-0000-0000-0000-000000000045', 'G2-ENG-PLURAL-01', 'PLURALS', 6, 'What is the plural of "mouse"?', 2, 'Mouse is irregular: one mouse, two mice.', 'This one changes completely.'),
    ('31000000-0000-0000-0000-000000000046', 'G2-ENG-SENTTYPE-01', 'SENTENCE_TYPES', 4, 'Which sentence is a command?', 1, 'A command tells someone to do something.', 'Which one tells you to do something?'),
    ('31000000-0000-0000-0000-000000000047', 'G2-ENG-SENTTYPE-01', 'SENTENCE_TYPES', 5, 'What mark ends a question?', 2, 'Questions end with a question mark.', 'Questions ask.'),
    ('31000000-0000-0000-0000-000000000048', 'G2-ENG-SENTTYPE-01', 'SENTENCE_TYPES', 6, 'Which sentence asks something?', 2, 'It asks something and ends with ?.', 'Look for the question mark.'),
    ('31000000-0000-0000-0000-000000000049', 'G2-ENG-MAINIDEA-01', 'MAIN_IDEA', 4, 'Read: "Owls hunt at night. They have big eyes to see in the dark. They fly without a sound." What is the main idea?', 2, 'Every sentence tells how owls hunt at night.', 'What do all the sentences have in common?'),
    ('31000000-0000-0000-0000-000000000050', 'G2-ENG-MAINIDEA-01', 'MAIN_IDEA', 5, 'Read: "Our class cleaned the park. We picked up trash and planted flowers." What is it mostly about?', 2, 'The main idea is the class cleaning the park.', 'Look at the first sentence.'),
    ('31000000-0000-0000-0000-000000000051', 'G2-ENG-MAINIDEA-01', 'MAIN_IDEA', 6, 'Read: "Apples can be red, green, or yellow. They grow on trees. They are sweet and crunchy." What is the main idea?', 2, 'Each sentence gives a fact about apples.', 'What is every sentence about?'),
    ('31000000-0000-0000-0000-000000000052', 'G2-EVENODD-01', 'EVEN_ODD', 1, 'Is 8 even or odd?', 1, '8 can be split into two equal groups of 4, so it is even.', 'Can you make pairs with nothing left over?'),
    ('31000000-0000-0000-0000-000000000053', 'G2-EVENODD-01', 'EVEN_ODD', 2, 'Is 7 even or odd?', 2, '7 makes 3 pairs with 1 left over, so it is odd.', 'Try making pairs.'),
    ('31000000-0000-0000-0000-000000000054', 'G2-EVENODD-01', 'EVEN_ODD', 3, 'Which number is even?', 2, '12 ends in 2, so it is even.', 'Even numbers end in 0, 2, 4, 6, or 8.'),
    ('31000000-0000-0000-0000-000000000055', 'G2-EVENODD-01', 'EVEN_ODD', 4, 'Which number is odd?', 2, '13 ends in 3, so it is odd.', 'Odd numbers end in 1, 3, 5, 7, or 9.'),
    ('31000000-0000-0000-0000-000000000056', 'G2-EVENODD-01', 'EVEN_ODD', 5, 'What is the next even number after 16?', 0, 'Even numbers go up by 2: 16, 18.', 'Count by 2s.'),
    ('31000000-0000-0000-0000-000000000057', 'G2-EVENODD-01', 'EVEN_ODD', 6, 'Is 20 even or odd?', 2, '20 ends in 0, so it is even: 10 + 10.', 'Look at the last digit.'),
    ('31000000-0000-0000-0000-000000000058', 'G2-ENG-PUNCT-01', 'PUNCTUATION_G2', 1, 'Which sentence is written correctly?', 2, 'Sentences start with a capital, and names of places and months are capitalized too.', 'Check every capital letter.'),
    ('31000000-0000-0000-0000-000000000059', 'G2-ENG-PUNCT-01', 'PUNCTUATION_G2', 2, 'Where do the commas go? "I like apples pears and plums."', 1, 'Commas separate items in a list.', 'Commas go between the list items.'),
    ('31000000-0000-0000-0000-000000000060', 'G2-ENG-PUNCT-01', 'PUNCTUATION_G2', 3, 'Which end mark fits: "Watch out for the car_"', 2, 'It is a strong, urgent warning, so use !.', 'Is it shouted?'),
    ('31000000-0000-0000-0000-000000000061', 'G2-ENG-PUNCT-01', 'PUNCTUATION_G2', 4, 'Which word needs a capital letter?', 0, 'Days of the week always start with a capital.', 'Find a day of the week.'),
    ('31000000-0000-0000-0000-000000000062', 'G2-ENG-PUNCT-01', 'PUNCTUATION_G2', 5, 'Which sentence has the correct end mark?', 0, 'It asks a question, so it ends with ?.', 'Is it asking something?'),
    ('31000000-0000-0000-0000-000000000063', 'G2-ENG-PUNCT-01', 'PUNCTUATION_G2', 6, 'Which is the correct way to write a date?', 1, 'Capitalize the month and put a comma between the day and the year.', 'The comma goes before the year.');
